Property Value Page Title New KYC Request Authorization IS_REQUESTOR (or NOT_ADMIN for broader access) Page Mode Normal Template Minimal (no left nav) <p>Page Items:</p> Item Name Type Source Validation P70_REQUESTOR_NAME Display Only <code>SELECT full_name FROM QD_KYC_USERS WHERE user_id = :APP_USER_ID</code> — P70_DEPARTMENT Display Only From APP_DEPT_ID — P70_ENTITY_NAME Text Field User entry NOT NULL P70_ENTITY_TYPE Select List Static: NATURAL_PERSON / LEGAL_ENTITY NOT NULL P70_ENTITY_COUNTRY Select List <code>SELECT country_name FROM QD_KYC_REF_COUNTRY ORDER BY country_name</code> NOT NULL P70_OWNERSHIP_CAT Select List Static: 6 ownership categories NOT NULL P70_RELATIONSHIP_TYPE Select List <code>SELECT rel_name, rel_type_id FROM QD_KYC_REF_RELATIONSHIP WHERE is_active='Y'</code> NOT NULL P70_FINANCIAL_FLAG Radio Group Static: CURRENT / PROPOSED / NONE NOT NULL P70_RELATED_PARTY Radio Group Static: Y / N NOT NULL P70_RELATED_DETAILS Textarea User entry Conditional: required if P70_RELATED_PARTY = Y P70_KYC_RESULT Display Only Computed by Ajax callback — P70_FILES File Upload Multiple files NOT NULL <p>Dynamic Action: Real-time KYC necessity check - Event: Change on P70_OWNERSHIP_CAT, P70_RELATIONSHIP_TYPE, P70_FINANCIAL_FLAG, P70_RELATED_PARTY - Action: Execute Server-side Code (Ajax) - PL/SQL: <code>RETURN QD_KYC_RULES.IS_KYC_REQUIRED(:P70_OWNERSHIP_CAT, :P70_RELATIONSHIP_TYPE, :P70_FINANCIAL_FLAG, :P70_RELATED_PARTY);</code> - Set P70_KYC_RESULT — apply CSS class based on Y/N result</p> <p>Page Process: Submit </p><pre><code>DECLARE
  v_intake_id  NUMBER;
  v_kyc_req    CHAR(1);
BEGIN
  v_kyc_req := QD_KYC_RULES.IS_KYC_REQUIRED(
    :P70_OWNERSHIP_CAT, :P70_RELATIONSHIP_TYPE,
    :P70_FINANCIAL_FLAG, :P70_RELATED_PARTY);

  INSERT INTO QD_KYC_INTAKE (
    requestor_user_id, department_id, entity_name, entity_type,
    entity_country, ownership_category, relationship_type_id,
    financial_involvement, related_party_flag, related_party_details,
    kyc_required, status, submission_date
  ) VALUES (
    :APP_USER_ID, :APP_DEPT_ID, :P70_ENTITY_NAME, :P70_ENTITY_TYPE,
    :P70_ENTITY_COUNTRY, :P70_OWNERSHIP_CAT, :P70_RELATIONSHIP_TYPE,
    :P70_FINANCIAL_FLAG, :P70_RELATED_PARTY, :P70_RELATED_DETAILS,
    v_kyc_req, 'SUBMITTED', SYSTIMESTAMP
  ) RETURNING intake_id INTO v_intake_id;

  -- Process uploaded files
  QD_KYC_DOCS.SAVE_APEX_FILES(
    p_intake_id  =&gt; v_intake_id,
    p_file_names =&gt; :P70_FILES
  );

  -- Launch workflow if KYC required
  IF v_kyc_req = 'Y' THEN
    QD_KYC_WORKFLOW.LAUNCH(p_intake_id =&gt; v_intake_id);
  END IF;

  -- Send confirmation
  QD_KYC_NOTIFICATIONS.SEND('INTAKE_RECEIVED', :APP_USER_ID, NULL, v_intake_id);

  :P70_INTAKE_ID := v_intake_id;
END;
</code></pre><p></p>

